from functools import lru_cache

def solve():
    n = int(input())
    @lru_cache(None)
    def get_max(i, prefix):
        if i == n:
            return prefix[0]
        max_val = 0
        for j in range(i, n):
            max_val = max(max_val, get_max(j + 1, prefix + [j] + list(reversed(prefix[i:j]))))
        return max_val + prefix[i]

