def create_graph(board_size, start, end):
    graph = defaultdict(list)
    size = board_size[0] * board_size[1]
    for i in range(size):
        neighbors = []
        if i % board_size[1] != board_size[1] - 1:
            neighbors.append(i + 1)
        if i != 0:
            neighbors.append(i - 1)
        if i % board_size[1] != 0 and i != 0:
            neighbors.append(i + board_size[1] + ((i - 1) // board_size[1]))
        graph[i] = neighbors
    graph[start] = []
    graph[end] = []
    return graph

def dfs(node, depth, graph, move_counts, memo):
    if node in memo:
        return memo[node]
    if depth > len(move_counts):
        return False
    if node == graph[0][0]:
        memo[node] = dfs(graph[node][0], depth + 1, graph, move_counts, memo)
    for neighbor in graph[node]:
        memo[node] = (memo[node] or dfs(neighbor, depth + 1, graph, move_counts, memo)) and any(dfs(neighbor, depth + move_counts[neighbor], graph, move_counts, memo) for i in range(1, 4, 2))
    return memo[node]

