class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if len(self.items) > 0:
            return self.items.pop()

    def min_top(self):
        if len(self.items) > 0:
            return min(self.items[-2], self.items[-1])

    def max_top(self):
        if len(self.items) > 0:
            return max(self.items[-2], self.items[-1])

def solve(a, b):
    a_stack = Stack()
    b_stack = Stack()

    a_count = len(a)
    b_count = len(b)

    for i in range(a_count):
        a_stack.push(int(a[i]))

    for i in range(b_count):
        b_stack.push(int(b[i]))

    while a_count > 0 and b_count > 0:
        if a_stack.min_top() > b_stack.min_top():
            a_stack.pop()
            a_stack.push(a_stack.min_top())
        elif a_stack.max_top() < b_stack.max_top():
            a_stack.pop()
            a_stack.push(a_stack.max_top())
        elif a_stack != b_stack:
            return 'NO'
        else:
            a_count -= 1
            b_count -= 1

    return 'YES' if a_count == b_count else 'NO'

