```python
from typing import List, Dict
import sys

def dp(a: List[List[int]], n: int, m: int, visited: Dict[str, int], memo: Dict[str, int]) -> int:
    key = (n, m)
    if key in memo:
        return memo[key]
    if n == 1 and m == 1:
        memo[key] = 0
        return 0
    if n == 1 or m == 1:
        cost = sys.maxsize
    else:
        cost = min(dp(a, n - 1, m, visited, memo) + a[n - 1][m - 1], dp(a, n, m - 1, visited, memo) + a[n - 1][m - 1])

    visited[(n, m)] = 1
    for i in range(n - 1, 0, -1):
        for j in range(m):
            if not visited[(i, j)] and dp(a, i - 1, j, visited, memo) + a[i - 1][j] < cost:
                cost = dp(a, i - 1, j, visited, memo) + a[i - 1][j]

    for j in range(m + 1, m * n):
        i = (j - 1) // m + 1
        if not visited[(i, (j - 1) % m)] and dp(a, i, (j - 1) % m, visited, memo) + a[i - 1][(j - 1) % m] < cost:
            cost = dp(a, i, (j - 1) % m, visited, memo) + a[i - 1][(j - 1) % m]

    memo[key] = cost
    visited[(n, m)] = 0
    return cost

